    });
    var playState = state.PlayState || {};
    var resumePositionTicks = playState.PositionTicks || 0;
    var playlistIndex = playlistIds.indexOf(item.Id) || 0;
    playbackManager.stop(oldPlayer).then(function () {
      playbackManager.play({
